use capablanca_chess_plus::{Position, Variant};
use llm_match::grounder::ControlGraph;
use serde_json::{Value, json};

const FEN: &str = "7k/8/8/4p3/3P4/P7/8/R1r1K3 w - - 0 1";
fn position() -> Position {
    Position::from_fen(Variant::Classic.rules(), FEN).unwrap()
}
fn map() -> Value {
    // Hand-authored geometry, never generated by engine attack helpers.
    json!({"version":1,"pieces":[
        {"id":"wR_a1","square":"a1","controls":["c1","b1","a3","a2"]},
        {"id":"wP_a3","square":"a3","controls":["b4"]},
        {"id":"wP_d4","square":"d4","controls":["c5","e5"]},
        {"id":"bP_e5","square":"e5","controls":["d4","f4"]},
        {"id":"wK_e1","square":"e1","controls":["d1","d2","e2","f1","f2"]},
        {"id":"bR_c1","square":"c1","controls":["a1","b1","c2","c3","c4","c5","c6","c7","c8","d1","e1"]},
        {"id":"bK_h8","square":"h8","controls":["g7","g8","h7"]}
    ]})
}
fn parse(value: Value) -> anyhow::Result<ControlGraph> {
    ControlGraph::parse(&position(), &value.to_string())
}

#[test]
fn occupancy_links_and_empty_square_controllers() {
    let graph = parse(map()).unwrap();
    let rook = graph.get_piece("wR_a1").unwrap();
    assert_eq!(rook.controls, ["a2", "a3", "b1", "c1"]);
    assert_eq!(rook.attacks_enemies, ["bR_c1"]);
    assert_eq!(rook.defends_allies, ["wP_a3"]);
    assert_eq!(graph.get_piece("wP_a3").unwrap().defended_by, ["wR_a1"]);
    assert_eq!(graph.get_attackers("b1").unwrap(), ["bR_c1", "wR_a1"]);
    assert_eq!(graph.get_square("b1").unwrap().occupant, None);
    assert_eq!(
        graph.get_square("a3").unwrap().occupant.as_deref(),
        Some("wP_a3")
    );
    assert!(graph.get_attackers("a4").unwrap().is_empty()); // ray ends at friendly pawn
    assert!(graph.get_attackers("d4").unwrap().contains(&"bP_e5".into()));
    assert_eq!(graph.get_piece("wP_d4").unwrap().attacks_enemies, ["bP_e5"]);
    assert!(!graph.get_attackers("d5").unwrap().contains(&"wP_d4".into()));
    assert!(graph.get_piece("bN_a1").is_none());
    assert!(graph.get_square("A1").is_err());
}

#[test]
fn pinned_knight_still_controls_squares() {
    let p = Position::from_fen(
        Variant::Classic.rules(),
        "4r1k1/8/8/8/8/8/4N3/4K3 w - - 0 1",
    )
    .unwrap();
    let value = json!({"version":1,"pieces":[
        {"id":"wN_e2","square":"e2","controls":["c1","c3","d4","f4","g1","g3"]},
        {"id":"wK_e1","square":"e1","controls":["d1","d2","e2","f1","f2"]},
        {"id":"bK_g8","square":"g8","controls":["f7","f8","g7","h7","h8"]},
        {"id":"bR_e8","square":"e8","controls":["a8","b8","c8","d8","e2","e3","e4","e5","e6","e7","f8","g8"]}
    ]});
    let graph = ControlGraph::parse(&p, &value.to_string()).unwrap();
    assert_eq!(graph.get_attackers("c3").unwrap(), ["wN_e2"]);
    assert_eq!(graph.get_piece("wN_e2").unwrap().defended_by, ["wK_e1"]);
    assert_eq!(graph.get_piece("bR_e8").unwrap().attacks_enemies, ["wN_e2"]);
}

#[test]
fn incorrect_geometry_is_neither_checked_nor_repaired() {
    let mut value = map();
    value["pieces"][0]["controls"] = json!(["h8"]); // rook a1 cannot control h8
    let graph = parse(value).unwrap();
    assert_eq!(graph.get_piece("wR_a1").unwrap().controls, ["h8"]);
    assert_eq!(graph.get_piece("wR_a1").unwrap().attacks_enemies, ["bK_h8"]);
    assert!(graph.get_attackers("a2").unwrap().is_empty());
}

#[test]
fn normalization_and_fenced_json_roundtrip() {
    let graph = parse(map()).unwrap();
    let normalized = graph.normalized_json().unwrap();
    let again = ControlGraph::parse(&position(), &format!("```json\n{normalized}\n```")).unwrap();
    assert_eq!(normalized, again.normalized_json().unwrap());
    let ids: Vec<_> = again.map().pieces.iter().map(|p| &p.id).collect();
    assert!(ids.windows(2).all(|w| w[0] < w[1]));
    for invalid in [
        "not json".to_string(),
        format!("comment {normalized}"),
        format!("{normalized} trailing"),
        r#"{"version":1,"version":1,"pieces":[]}"#.into(),
    ] {
        assert!(ControlGraph::parse(&position(), &invalid).is_err());
    }
}

#[test]
fn bad_schema_inventory_and_coordinates_have_specific_errors() {
    let cases: Vec<(&str, Value)> = vec![
        ("version", {
            let mut v = map();
            v["version"] = json!(2);
            v
        }),
        ("unknown field", {
            let mut v = map();
            v["evaluation"] = json!(0);
            v
        }),
        ("unknown field", {
            let mut v = map();
            v["pieces"][0]["type"] = json!("Rook");
            v
        }),
        ("missing field", {
            let mut v = map();
            v["pieces"][0].as_object_mut().unwrap().remove("controls");
            v
        }),
        ("missing pieces", {
            let mut v = map();
            v["pieces"].as_array_mut().unwrap().remove(0);
            v
        }),
        ("duplicate piece id", {
            let mut v = map();
            let p = v["pieces"][0].clone();
            v["pieces"].as_array_mut().unwrap().push(p);
            v
        }),
        ("duplicate piece square", {
            let mut v = map();
            v["pieces"][1]["square"] = json!("a1");
            v
        }),
        ("expected wR_a1", {
            let mut v = map();
            v["pieces"][0]["id"] = json!("bR_a1");
            v
        }),
        ("expected wR_a1", {
            let mut v = map();
            v["pieces"][0]["id"] = json!("wN_a1");
            v
        }),
        ("is empty", {
            let mut v = map();
            v["pieces"][0]["square"] = json!("a2");
            v
        }),
        ("duplicate controlled square", {
            let mut v = map();
            v["pieces"][0]["controls"] = json!(["a2", "a2"]);
            v
        }),
    ];
    for (expected, value) in cases {
        let error = format!("{:#}", parse(value).unwrap_err());
        assert!(error.contains(expected), "{expected}: {error}");
    }
    for invalid in ["A1", "a01", "a0", "a9", "i1", "a18", "", " a1", "a1 ", "а1"] {
        let mut value = map();
        value["pieces"][0]["controls"] = json!([invalid]);
        assert!(format!("{:#}", parse(value).unwrap_err()).contains("coordinate"));
        let mut value = map();
        value["pieces"][0]["square"] = json!(invalid);
        assert!(parse(value).is_err());
    }
    assert!(ControlGraph::parse(&Variant::Gothic.starting_position(), &map().to_string()).is_err());
}

#[test]
fn offline_cli_works_without_configuration_or_server() {
    let path = std::env::temp_dir().join(format!("grounder-map-{}.json", std::process::id()));
    std::fs::write(&path, map().to_string()).unwrap();
    let run = |extra: &[&str]| {
        std::process::Command::new(env!("CARGO_BIN_EXE_llm-match"))
            .env("LLM_MATCH_ENV", "/nonexistent/grounder-test.env")
            .args(["--stage", "grounder", "--fen", FEN, "--grounder-map-file"])
            .arg(&path)
            .args(extra)
            .output()
            .unwrap()
    };
    let result = run(&[]);
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    assert_eq!(
        String::from_utf8(result.stdout).unwrap().trim(),
        parse(map()).unwrap().normalized_json().unwrap()
    );
    let result = run(&["--inspect-square", "b1", "--inspect-piece", "wR_a1"]);
    assert!(result.status.success());
    let v: Value = serde_json::from_slice(&result.stdout).unwrap();
    assert_eq!(v["square"]["controlled_by"], json!(["bR_c1", "wR_a1"]));
    assert_eq!(v["piece"]["attacks_enemies"], json!(["bR_c1"]));
    for args in [
        vec!["--print-prompt"],
        vec!["--stage", "proposer"],
        vec!["--variant", "Gothic"],
        vec!["--inspect-square", "a9"],
        vec!["--inspect-piece", "bad"],
        vec!["--fen", "7k/8/8/8/8/8/8/K7 w - - 0 1"],
    ] {
        assert!(!run(&args).status.success());
    }
    std::fs::remove_file(path).unwrap();
}
